-- Splynn Dimensional Market: 16 priced market goods from the shops of printed 21-36.
-- 16 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~362-splynn-market-goods.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('magic-in-a-vial', 'Magic in a Vial', 'rifts', 'magic', NULL, 45000, '45,000 credits a vial; the shop sells no more than two to a customer', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Plain water charged with raw P.P.E., which only the Water Merchant in the Splynn Dimensional Market seems able to supply. Drinking a vial gives 20 extra P.P.E. that fade after 1D6+8 minutes, so it is spent quickly: mages use it to refill or to boost before combat, and someone with no magic can use it to run a Techno-Wizard device for a short while. The body tops out at 40 extra P.P.E. this way (60 for a practitioner of magic), so further vials add nothing, and going past two brings on a headache, irritability and the other signs of ley line overexposure for 1D4 hours. A mage whose own P.P.E. is already full gains only 10 from a vial. It does nothing for creatures of magic or supernatural beings. Supply runs short for weeks at a time.', 'Rifts World Book 21: Splynn Dimensional Market p.21', NULL),
  ('nectar-of-dionna', 'Nectar of Dionna', 'rifts', 'magic', NULL, 1000, '1,000 credits a glass; 15,000 credits a bottle (the book says it could fetch ten times that elsewhere)', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The house wine of Chaotic Spirits, Dionna''s tavern in the Splynn Dimensional Market, and reputedly her own recipe. Besides acting as any wine does, it can make supernatural beings drunk: a supernatural drinker saves vs magic or feels it, and the effect builds with each drink until even a greater demon or a god is thoroughly drunk. A mortal such as a human who takes even a sip saves vs magic at -4 or drops into a coma-like stupor for 1D4 hours. A mortal who drinks a whole glass must roll against coma and death at -15%; failing means the heart stops, and only extreme medical measures or life-saving magic will revive him.', 'Rifts World Book 21: Splynn Dimensional Market p.27', NULL),
  ('wardrobe-amulet', 'Wardrobe Amulet', 'rifts', 'magic', NULL, 500000, '500,000 credits for a standard amulet; up to 2 million credits for one with outfits the buyer chooses', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The top seller at Enchanted Apparel in the Splynn Dimensional Market: a magic gem that, when rubbed, cloaks the wearer in an illusion of clothing, even if he has nothing on underneath. It holds four outfits set in advance. Shapechangers like it because the illusory clothes change shape with them; mages wear it for elegance, thieves and spies for fast changes and disguise, and warriors to look freshly dressed after a fight.', 'Rifts World Book 21: Splynn Dimensional Market p.28-29', NULL),
  ('the-butterfly', 'The Butterfly', 'rifts', 'magic', NULL, 500, '500 credits a human-sized dose', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The house special of Butterfly Fields, a hallucinogen shop in the Splynn Dimensional Market: a magically made powder that is inhaled. For 1D4 hours his astral form leaves the body and drifts at random through the Astral Plane, with no conscious steering and his thinking dulled; most users take the trip for a dream. Once it ends he is dazed for 1D6 hours, at one fewer melee attack and half skill performance. The Astral Plane''s inhabitants mostly ignore these harmless Butterfly Zombies, and the traveller floats back to his body as the drug fades, unless it wears off too abruptly (possible for someone who regenerates) and he panics.', 'Rifts World Book 21: Splynn Dimensional Market p.29', NULL),
  ('time-master', 'Time Master', 'rifts', 'magic', NULL, 5000, '5,000-15,000 credits, by artistry and gems', NULL, 0, NULL, NULL, NULL, NULL, NULL, 15, 'The basic Techno-Wizard pocket watch from Tick Tock Timepieces, made in the Splynn Dimensional Market by the Gemini Demon brothers Tyk (a Techno-Wizard) and Tak (a Temporal Wizard). It keeps perfect time and never needs winding, running on 1 P.P.E. every 24 hours drawn from its wearer or from ley line energy. It shrugs off heavy shocks, falls and water pressure and has a built-in alarm. Its entry gives it 15 M.D.C., overriding the shop''s usual 60. The Auto-Timer Spellcaster and the Time Traveler are built on it.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('the-time-traveler', 'The Time Traveler', 'rifts', 'magic', NULL, 3000000, '3-5 million credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market. It does everything the Time Master does, is immune to time distortion, and shows two times at once: the time back in the home dimension (presumably Rifts Earth) and the time the wearer is actually living through in alien dimensions and in Time Holes, Loops and Pockets, wherever time runs differently or stands still. It stays accurate under reality-bending magic such as Fast Forward Time, T-Dep, D-Phase, D-Shift: Two Dimensions and D-Shift Phantom. M.D.C. stored as the shop''s general 60, since this entry states none; it carries the Time Master''s attributes, and that entry says 15.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('time-keeper', 'Time Keeper', 'rifts', 'magic', NULL, 60000000, '60-75 million credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market. It has every ability of the Time Traveler and adds Suspended Animation/Stasis Field, a Temporal Magic spell that affects only its wearer and can be set for as long as 70 years, waking him at a chosen moment down to the minute. Duration is as the spell at 7th level. As with all the shop''s watches, the user must put the P.P.E. into the watch himself; the entry prints no figure for it. M.D.C. stored as the shop''s general 60, since this entry states none.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('auto-timer-spellcaster', 'Auto-Timer Spellcaster', 'rifts', 'magic', NULL, 4000000, '4-6 million credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market, with the Time Master''s features and one built-in Wizard spell of level 1 to 6. It works like a talisman, except that the spell''s usual P.P.E. is loaded in advance and the spell goes off at a time set on the alarm, up to 24 hours later, whether or not the owner remembers or still wants it. The spells chosen are defensive, protective or concealing (Armor of Ithan, Chameleon, Globe of Daylight, Shadow Meld, Escape, Invulnerability, Mask of Deceit, Breathe Without Air, or Mute on oneself to resist interrogation); combat and attack spells cannot be built in. Duration is as 10th level. One spell per watch. M.D.C. stored as the shop''s general 60, since this entry states none.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('eyes-of-time', 'Eyes of Time', 'rifts', 'magic', NULL, 10000000, '10-20 million credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market, its cover shaped as one large eye or a pair of eyes, often with gems for pupils. It casts either of two Temporal Magic spells, one at a time: Remote Viewing for 45 P.P.E. or Retro-Viewing for 30 P.P.E., the P.P.E. put in by the user. The images show on the watch face, so the cover has to be open. Duration and range are as 7th level.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('the-stopwatch', 'The Stopwatch', 'rifts', 'magic', NULL, 1000000, '1 to 1.5 million credits, by artistry and jewels', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market, usually silver or silver-plated (some white gold), with jewels set in the cover where the hour marks fall. Putting in 20 P.P.E. and pressing a button produces the effect of the Wizard and Temporal Magic spell Time Slip.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('the-snail', 'The Snail', 'rifts', 'magic', NULL, 4000000, '4-6 million credits, by artistry and jewels', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A gold Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market, usually made to look like a big snail shell, though serpent coils and ram''s heads are popular too, and some are set with gems. Putting in 50 P.P.E. and winding its spring produces the spell Speed of the Snail, cast at 8th level.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('the-turtle', 'The Turtle', 'rifts', 'magic', NULL, 2000000, '2-3 million credits, by artistry', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'A Techno-Wizard pocket watch from Tyk and Tak''s Tick Tock Timepieces in the Splynn Dimensional Market, shaped like a small turtle shell, mostly gold or gold-plated and studded with jewels. Putting in 25 P.P.E. and pressing a button produces Time Warp: Slow Motion, a Temporal Magic spell, cast at 8th level.', 'Rifts World Book 21: Splynn Dimensional Market p.30-31', NULL),
  ('mdc-leathers-light-suit', 'M.D.C. Leathers, Light Suit', 'rifts', 'armor', NULL, 20000, '20,000-40,000 credits; 30% to 100% more for elaborate custom designs, artwork or gems', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'Patchwork armour of M.D.C. hides, leather and bone from Wrapped in Leather in the Splynn Dimensional Market, where monsters buy it for its comfort and its look and the customer decides the design (wrapped vambraces, heavy shoulder pads and skull helmets are favourites). The light or human-sized suit has 50 to 75 M.D.C. (the column holds the low end) and a movement penalty of -5% to -15%. Seldom environmental; magic armour only by special request.', 'Rifts World Book 21: Splynn Dimensional Market p.34', NULL),
  ('mdc-leathers-heavy-suit', 'M.D.C. Leathers, Heavy Suit', 'rifts', 'armor', NULL, 60000, '60,000-100,000 credits; 30% to 100% more for elaborate custom designs, artwork or gems', NULL, 0, NULL, NULL, NULL, NULL, NULL, 90, 'Heavy plated patchwork armour of M.D.C. hides, leather and bone from Wrapped in Leather in the Splynn Dimensional Market, cut for wearers bigger than human, 7 to 10 feet (2.1 to 3 m) tall. It has 90 to 150 M.D.C. (the column holds the low end) and a movement penalty of -10% to -20%, doubled for a wearer with P.S. under 24 and halved for one with supernatural P.S. Seldom environmental; magic armour only by special request.', 'Rifts World Book 21: Splynn Dimensional Market p.34', NULL),
  ('mdc-leathers-giant-suit', 'M.D.C. Leathers, Giant Suit', 'rifts', 'armor', NULL, 100000, '100,000-250,000 credits; 30% to 100% more for elaborate custom designs, artwork or gems', NULL, 0, NULL, NULL, NULL, NULL, NULL, 180, 'Extremely heavy patchwork armour of M.D.C. hides, leather and bone from Wrapped in Leather in the Splynn Dimensional Market, sized for giants 12 to 30 feet (3.6 to 9 m) tall. It has 180 to 250 M.D.C. (the column holds the low end) and a movement penalty of -25% to -35%. Only a being with supernatural P.S. of 24 or more can wear it properly; a human or D-Bee can hardly move in one. Seldom environmental; magic armour only by special request.', 'Rifts World Book 21: Splynn Dimensional Market p.34', NULL),
  ('venom-of-the-midgard-serpent', 'Venom of the Midgard Serpent', 'rifts', 'magic', NULL, 1000000, 'No less than 1 million credits a dose; rarely in stock', '1D6x10 M.D. per melee round for 1D6 rounds; 1D6x10 damage direct to Hit Points against mortals', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The strongest poison the Snake Venom shop in the Splynn Dimensional Market ever has, taken from the Midgard Serpent of Asgard. It works on dragons, other creatures of magic and most, though not all, supernatural beings; the undead are immune, and ancient dragons, demon lords, demigods and gods take half damage. One dose also shuts down the victim''s regeneration for 3D4 minutes, leaving him open to further attack, and a single dose kills many lesser supernatural creatures. Against a mortal it does 1D6x10 straight to Hit Points and causes violent vomiting, halving his melee attacks, speed and combat bonuses for 3D4 melee rounds.', 'Rifts World Book 21: Splynn Dimensional Market p.36', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 16 gear rows are in' AS assertion, count(*) AS got, 16 AS want
  FROM gear WHERE slug IN ('magic-in-a-vial', 'nectar-of-dionna', 'wardrobe-amulet', 'the-butterfly', 'time-master', 'the-time-traveler', 'time-keeper', 'auto-timer-spellcaster', 'eyes-of-time', 'the-stopwatch', 'the-snail', 'the-turtle', 'mdc-leathers-light-suit', 'mdc-leathers-heavy-suit', 'mdc-leathers-giant-suit', 'venom-of-the-midgard-serpent') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~362-splynn-market-goods.sql');
